from .string_distance import MetricStringDistance


class SIFT4Options(MetricStringDistance):
    def __init__(self, options=None):
        """Initialize SIFT4Options with default or custom options.

        Args:
            options: Dictionary containing custom options for SIFT4 algorithm.
                    If None, default options will be used.
        """
        # Set default options
        self.tokenizer = self.ngramtokenizer
        self.tokenmatcher = self.sift4tokenmatcher
        self.matchingevaluator = self.sift4matchingevaluator
        self.locallengthevaluator = self.rewardlengthevaluator
        self.transpositioncostevaluator = self.longertranspositionsaremorecostly
        self.transpositionsevaluator = lambda lcss, trans: lcss - trans
        self.maxdistance = 0

        # Override with custom options if provided
        if options:
            for key, value in options.items():
                setattr(self, key, value)
    # tokenizers:
    @staticmethod
    def ngramtokenizer(s, n):
        result = []
        if not s:
            return result
        for i in range(len(s) - n - 1):
            result.append(s[i:(i + n)])
        return result

    @staticmethod
    def wordsplittokenizer(s):
        if not s:
            return []
        return s.split()

    @staticmethod
    def characterfrequencytokenizer(s):
        letters = [i for i in 'abcdefghijklmnopqrstuvwxyz']
        return [s.lower().count(x) for x in letters]

    # tokenMatchers:
    @staticmethod
    def sift4tokenmatcher(t1, t2):
        similarity = 1 - SIFT4().distance(t1, t2, 5) / max(len(t1), len(t2))
        return similarity > 0.7

    # matchingEvaluators:
    @staticmethod
    def sift4matchingevaluator(t1, t2):
        similarity = 1 - SIFT4().distance(t1, t2, 5) / max(len(t1), len(t2))
        return similarity

    # localLengthEvaluators:
    @staticmethod
    def rewardlengthevaluator(l):
        if l < 1:
            return l
        return l - 1 / (l + 1)

    @staticmethod
    def rewardlengthevaluator2(l):
        return pow(l, 1.5)

    # transpositionCostEvaluators:
    @staticmethod
    def longertranspositionsaremorecostly(c1, c2):
        return abs(c2 - c1) / 9 + 1


